({ buffer, final, state = {} }) => {
  let out = String(buffer ?? '');
  // 若模型在调用工具前犯蠢先吐了野生 <think>...</think>，在闭合或收尾时直接从源头剥除
  if (out.includes('<think_nya') || out.includes('<report_nya') || final) {
    out = out.replace(
      /(?<!<!--\s*)<think(?:\s[^>]*)?>(?:(?!(?:<think_nya|<report_nya))[\s\S])*?(?:<\/think>(?!\s*-->)|(?=<(?:think_nya|report_nya)~?>))\s*/gi,
      ''
    );
  }
  return {
    output: out,
    hold: '',
    state: { ...state, accepted: true },
  };
}

toolCallFormatter.script:
({ calls, defaultText }) => {
  if (!Array.isArray(calls) || calls.length === 0) {
    return defaultText ?? '';
  }

  // 若所有具名工具调用均不属于猫神自身的回复工具（例如 MVU 的 mvu_VariableUpdate_* 或其他插件 Function Tool），
  // 主动抛出异常，让 SPreset 按官方契约放弃消费并原封不动退还原始 tool_calls 给酒馆与对应插件处理。
  const namedCalls = calls
    .map(c => String(c?.name ?? c?.function?.name ?? '').trim())
    .filter(Boolean);
  if (
    namedCalls.length > 0 &&
    namedCalls.every(name => !/^(?:soliumbra_reply|reply)$/i.test(name))
  ) {
    throw new Error('External tool call passthrough');
  }

  const unescapeJsonStr = str =>
    str
      .replace(/\\n/g, '\n')
      .replace(/\\r/g, '\r')
      .replace(/\\t/g, '\t')
      .replace(/\\"/g, '"')
      .replace(/\\\\/g, '\\');

  // 流式半截 JSON 字符串兜底提取器
  const parsePartialArgs = raw => {
    const res = {};
    const keyRegex = /"([a-zA-Z0-9_]+)"\s*:\s*"((?:\\.|[^"\\])*)/g;
    let m;
    while ((m = keyRegex.exec(raw)) !== null) {
      res[m[1]] = unescapeJsonStr(m[2]);
    }
    return res;
  };

  // 仅在此表中的字段才自动补齐对应标签；extra / story_body 及其他额外字段一律原样输出不包标签
  const tagMap = {
    think_nya: 'think_nya',
    game_content: 'game',
    game: 'game',
    options: 'options',
    summary: 'summary',
    comment: 'comment',
  };

  const wrapTag = (val, tag) => {
    const trimmed = String(val ?? '').trim();
    if (!trimmed || !tag) return trimmed;

    // 1. 若内容中已经带有目标标签 <tag>，直接原样返回，绝不重复包裹
    const hasTargetTag = new RegExp(`<${tag}[\\s>]`, 'i').test(trimmed);
    const hasTargetTagClose = new RegExp(`<\/${tag}[\\s>]`, 'i').test(trimmed);
    if (hasTargetTag && hasTargetTagClose) return trimmed;

    // 2. 若 comment 字段里模型用了 <details> 折叠块，也直接原样返回
    if (tag === 'comment' && /^<details[\s>]/i.test(trimmed)) {
      return trimmed;
    }

    // 3. 若用户在【<game>标签（可改）】里改成了别的自定义标签（如 <novel>...</novel>），检测首尾成对标签直接放行
    if (
      tag === 'game' &&
      /^<([a-zA-Z0-9_-]+)>[\s\S]*<\/\1>$/.test(trimmed)
    ) {
      return trimmed;
    }

    return `<${tag}>\n${trimmed}\n</${tag}>`;
  };

  return calls
    .map(call => {
      let args = call?.arguments;
      if (typeof args === 'string') {
        try {
          args = JSON.parse(args);
        } catch {
          args = parsePartialArgs(args);
        }
      }

      if (!args || typeof args !== 'object') {
        return typeof call?.arguments === 'string' ? call.arguments : '';
      }

      if (
        typeof args.content === 'string' &&
        Object.keys(args).length === 1
      ) {
        return args.content;
      }

      // 兜底兼容 MVU 额外模型解析：若自定义配置/反代误走了 soliumbra_reply，且返回内容纯粹只是 MVU 变量更新载荷，
      // 自动省去 <think_nya> 与 <game> 包裹，直接返回纯净的 JSON Patch 或 <UpdateVariable> 块供 MVU 解析。
      if (
        args.json_patch !== undefined &&
        !args.game_content &&
        !args.game &&
        !args.story_body
      ) {
        return JSON.stringify({
          analysis: String(args.analysis ?? args.analyze ?? ''),
          json_patch: args.json_patch,
        });
      }
      if (
        typeof args.delta === 'string' &&
        !args.game_content &&
        !args.game &&
        !args.story_body
      ) {
        return `<UpdateVariable>\n<Analyze>\n${String(args.analysis ?? '')}\n</Analyze>\n${args.delta}\n</UpdateVariable>`;
      }

      const nonThinkBusinessKeys = Object.keys(args).filter(
        k => k !== 'think_nya' && k !== 'nya_oath' && String(args[k] ?? '').trim() !== ''
      );
      if (
        nonThinkBusinessKeys.length === 1 &&
        /^(?:game_content|game|story_body)$/.test(nonThinkBusinessKeys[0])
      ) {
        const rawBody = String(args[nonThinkBusinessKeys[0]] ?? '').trim();
        const unfenced = rawBody
          .replace(/^```(?:json5?|ya?ml)?\s*/i, '')
          .replace(/\s*```$/, '')
          .trim();
        let isPureMvuPayload =
          /^<(?:UpdateVariable|VariableUpdate|JSONPatch|json_patch)\b[^>]*>[\s\S]*<\/(?:UpdateVariable|VariableUpdate|JSONPatch|json_patch)>$/i.test(
            unfenced
          );
        if (!isPureMvuPayload && /^[\[{][\s\S]*[\]}]$/.test(unfenced)) {
          try {
            const parsedObj = JSON.parse(unfenced);
            if (
              Array.isArray(parsedObj) &&
              (parsedObj.length === 0 ||
                parsedObj.every(
                  item =>
                    item &&
                    typeof item === 'object' &&
                    typeof item.op === 'string' &&
                    typeof item.path === 'string'
                ))
            ) {
              isPureMvuPayload = true;
            } else if (
              parsedObj &&
              typeof parsedObj === 'object' &&
              (Array.isArray(parsedObj.json_patch) ||
                Array.isArray(parsedObj.jsonPatch) ||
                typeof parsedObj.json_patch === 'string')
            ) {
              isPureMvuPayload = true;
            }
          } catch {
            /* not pure JSON */
          }
        }
        if (isPureMvuPayload) {
          return rawBody;
        }
      }

      const priorityOrder = [
        'think_nya',
        'game_content',
        'game',
        'story_body',
        'extra',
        'options',
        'summary',
        'comment',
      ];
      const extraKeys = Object.keys(args).filter(
        k => !priorityOrder.includes(k) && k !== 'nya_oath'
      );
      const finalKeyOrder = [...priorityOrder, ...extraKeys];

      const parts = [];

      for (const key of finalKeyOrder) {
        if (!(key in args)) continue;
        let val = String(args[key] ?? '').trim();
        if (!val) continue;

        if (key === 'think_nya') {
          if (/^\[?\s*REDACTED\b/i.test(val)) continue;
          val = val
            .replace(/`{3,}/g, '')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(
              /_\.(?=(?:set|insert|assign|remove|unset|delete|add)\s*\()/g,
              '_\u200c.'
            );
        }

        const tag = tagMap[key] ?? null;
        let wrapped = wrapTag(val, tag);
        if (key === 'think_nya' && wrapped && !wrapped.includes('<!--</think>-->')) {
          wrapped += '<!--</think>-->';
        }
        parts.push(wrapped);
      }

      return parts.filter(Boolean).join('\n');
    })
    .filter(Boolean)
    .join('\n\n');
};

